Below is a lightweight, dependency-minimal Python library you can drop into your project to interact with the MythTV Services API (HTTP/JSON, typically on port 6544). It provides a clean client with a few common endpoints pre-wrapped and a generic call method for anything not yet covered.

Save as mythtv.py.

import requests
from typing import Any, Dict, Optional, Union, List
from datetime import datetime, timezone
from urllib.parse import urlencode


class MythTVError(Exception):
    """Raised for MythTV client and API errors."""


class MythTVClient:
    """
    Simple client for the MythTV Services API.
    Default backend URL is http://<host>:6544.
    """

    def __init__(
        self,
        base_url: str,
        *,
        username: Optional[str] = None,
        password: Optional[str] = None,
        timeout: Union[int, float] = 10,
        default_params: Optional[Dict[str, Any]] = None,
        session: Optional[requests.Session] = None,
    ):
        """
        base_url: e.g. "http://mythbackend:6544"
        username/password: optional HTTP basic auth if your backend is protected by a reverse proxy, etc.
        timeout: per-request timeout
        default_params: query params always added (e.g. {"Token": "..."} if your setup needs it)
        session: optional custom requests.Session
        """
        self.base_url = base_url.rstrip("/")
        self.auth = (username, password) if username or password else None
        self.timeout = timeout
        self.default_params = default_params.copy() if default_params else {}
        self._s = session or requests.Session()
        self._s.headers.update({
            "Accept": "application/json",
            "User-Agent": "MythTVClient/1.0 (+https://www.mythtv.org/)"
        })

    # ---------- Utilities ----------

    @staticmethod
    def _to_myth_iso(dt: Union[str, datetime]) -> str:
        """
        Convert a datetime or ISO-like string to MythTV-expected ISO8601.
        MythTV generally accepts 'YYYY-MM-DDTHH:MM:SSZ' or without Z (local).
        We send UTC with Z when timezone-aware.
        """
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            # Assume naive datetime is local; send without timezone
            return dt.replace(microsecond=0).isoformat()
        # Convert to UTC with 'Z'
        return dt.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _build_url(self, service: str, method: str) -> str:
        return f"{self.base_url}/{service.strip('/')}/{method}"

    def _merge_params(self, params: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        merged = {}
        merged.update(self.default_params)
        if params:
            for k, v in params.items():
                if isinstance(v, bool):
                    merged[k] = "true" if v else "false"
                else:
                    merged[k] = v
        return merged

    def _request(
        self,
        service: str,
        method: str,
        *,
        params: Optional[Dict[str, Any]] = None,
        http_method: str = "GET",
        json_body: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        url = self._build_url(service, method)
        qp = self._merge_params(params)

        try:
            if http_method.upper() == "GET":
                resp = self._s.get(url, params=qp, timeout=self.timeout, auth=self.auth)
            elif http_method.upper() in ("POST", "PUT", "DELETE"):
                # MythTV Services API uses GET heavily; POST/PUT/DELETE for a few actions.
                resp = self._s.request(
                    http_method.upper(),
                    url,
                    params=qp if http_method.upper() != "POST" else None,
                    json=json_body,
                    timeout=self.timeout,
                    auth=self.auth,
                )
            else:
                raise MythTVError(f"Unsupported HTTP method: {http_method}")
        except requests.RequestException as e:
            raise MythTVError(f"Network error calling {service}/{method}: {e}") from e

        if not resp.ok:
            # Try to show MythTV error message if present
            detail = ""
            try:
                errj = resp.json()
                detail = f" Response JSON: {errj}"
            except Exception:
                detail = f" Response text: {resp.text[:300]}"
            raise MythTVError(f"HTTP {resp.status_code} calling {service}/{method}.{detail}")

        # Parse JSON
        try:
            data = resp.json()
        except ValueError as e:
            raise MythTVError(f"Invalid JSON from {service}/{method}: {e}. Body: {resp.text[:300]}") from e

        return data

    def call(self, service: str, method: str, *, params: Optional[Dict[str, Any]] = None, http_method: str = "GET", json_body: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """
        Generic call helper for any MythTV service/method.
        Example: client.call("Dvr", "GetRecordedList", params={"Descending": True})
        """
        return self._request(service, method, params=params, http_method=http_method, json_body=json_body)

    # ---------- Common Endpoints (Convenience) ----------

    # Myth service (general info)
    def get_version(self) -> Dict[str, Any]:
        return self.call("Myth", "GetVersion")

    def get_hostname(self) -> str:
        data = self.call("Myth", "GetHostName")
        # Usually returns {"String":"hostname"}
        return data.get("String") or data.get("HostName") or ""

    def get_host_status(self) -> Dict[str, Any]:
        return self.call("Myth", "GetHostStatus")

