        params = {"OnlyVisible": only_visible}
        if source_id is not None:
            params["SourceID"] = source_id
        data = self.call("Channel", "GetChannelList", params=params)
        # {"ChannelInfoList":{"ChannelInfos":[{...}]}}
        chans = data.get("ChannelInfoList", {}).get("ChannelInfos", [])
        if isinstance(chans, dict):
            chans = [chans]
        return chans

    # Guide service
    def get_program_guide(
        self,
        start_time: Union[str, datetime],
        end_time: Union[str, datetime],
        start_chan_id: Optional[int] = None,
        num_channels: Optional[int] = None,
        details: bool = False,
    ) -> Dict[str, Any]:
        params = {
            "StartTime": self._to_myth_iso(start_time),
            "EndTime": self._to_myth_iso(end_time),
            "Details": details,
        }
        if start_chan_id is not None:
            params["StartChanId"] = start_chan_id
        if num_channels is not None:
            params["NumChannels"] = num_channels
        return self.call("Guide", "GetProgramGuide", params=params)

    # DVR service
    def list_recordings(self, descending: bool = True, count: Optional[int] = None, offset: Optional[int] = None) -> List[Dict[str, Any]]:
        params = {"Descending": descending}
        if count is not None:
            params["Count"] = count
        if offset is not None:
            params["Offset"] = offset
        data = self.call("Dvr", "GetRecordedList", params=params)
        # {"ProgramList":{"Programs":[{...}], "Count": N, ...}}
        progs = data.get("ProgramList", {}).get("Programs", [])
        if isinstance(progs, dict):
            progs = [progs]
        return progs

    def get_recording(self, chan_id: int, start_time: Union[str, datetime]) -> Dict[str, Any]:
        params = {"ChanId": chan_id, "StartTime": self._to_myth_iso(start_time)}
        return self.call("Dvr", "GetRecorded", params=params)

    def delete_recording(self, chan_id: int, start_time: Union[str, datetime], force: bool = False) -> bool:
        params = {"ChanId": chan_id, "StartTime": self._to_myth_iso(start_time), "ForceDelete": force}
        data = self.call("Dvr", "RemoveRecorded", params=params)
        # Often returns {"bool":true}
        return bool(data.get("bool", True))

    def list_upcoming(self, show_all: bool = True) -> Dict[str, Any]:
        # Returns a structure with "ProgramList" similar to recorded list
        return self.call("Dvr", "GetUpcomingList", params={"ShowAll": show_all})

    def reschedule_recordings(self) -> bool:
        data = self.call("Dvr", "RescheduleRecordings")
        return bool(data.get("bool", True))

    # Content service (optional helpers)
    def get_file(self, storage_group: str, file_name: str, *, stream: bool = False):
        """
        Download or stream a file from Content service.
        Returns requests.Response if stream=True; otherwise returns bytes.
        """
        # MythTV content URL is typically /Content/GetFile?StorageGroup=...&FileName=...
        url = self._build_url("Content", "GetFile")
        params = self._merge_params({"StorageGroup": storage_group, "FileName": file_name})
        try:
            resp = self._s.get(url, params=params, timeout=self.timeout, auth=self.auth, stream=stream)
            resp.raise_for_status()
            return resp if stream else resp.content
        except requests.RequestException as e:
            raise MythTVError(f"Error downloading file from Content/GetFile: {e}") from e

    # ---------- Pagination helper ----------

    def paged(
        self,
        service: str,
        method: str,
        *,
        list_path: List[str],
        count_param: str = "Count",
        offset_param: str = "Offset",
        page_size: int = 200,
        extra_params: Optional[Dict[str, Any]] = None,
    ) -> List[Dict[str, Any]]:
        """
        Generic pagination helper for endpoints that support Count/Offset and return lists.
        list_path: path keys to reach the array in the response, e.g. ["ProgramList", "Programs"]
        """
        out: List[Dict[str, Any]] = []
        offset = 0
        while True:
            params = dict(extra_params or {})
            params[count_param] = page_size
            params[offset_param] = offset
            data = self.call(service, method, params=params)
            node: Any = data
            for k in list_path:
                node = node.get(k, {}) if isinstance(node, dict) else {}
            items = node
            if not items:
                break
            if isinstance(items, dict):
                items = [items]
            out.extend(items)
            if len(items) < page_size:
                break
            offset += page_size
        return out


