if __name__ == "__main__":
    # Replace with your backend address and port (default 6544)
    client = MythTVClient("http://localhost:6544")

    try:
        print("Backend host:", client.get_hostname())
        print("Version:", client.get_version())

        recordings = client.list_recordings(descending=True, count=10)
        print(f"Found {len(recordings)} recordings (showing up to 10).")
        if recordings:
            first = recordings[0]
            chan_id = first.get("Channel", {}).get("ChanId") or first.get("ChanId")
            start_time = first.get("Recording", {}).get("StartTs") or first.get("StartTime")
            print("First recording:", first.get("Title"), start_time, "ChanId:", chan_id)

        # Get 24h of guide starting now
        now = datetime.now()
        guide = client.get_program_guide(now, now.replace(hour=23, minute=59, second=59))
        pl = guide.get("ProgramGuide", {}).get("Channels", [])
        print("Guide channels returned:", len(pl))
    except MythTVError as e:
        print("MythTV error:", e)

Notes and tips:
- Base URL: usually http://<backend-host>:6544. If you proxy through HTTPS or add basic auth, pass username/password.
- If your deployment requires a token or custom query parameter, set default_params={"Token":"..."} when constructing the client; it will be added to every request.
- The API returns JSON with nested structures and sometimes singular objects instead of arrays; this client normalizes some common cases but returns raw JSON for general calls so you can handle details as needed.
- If you need additional endpoints, use client.call("Service", "Method", params={...}) or add convenience wrappers similar to those provided.

